//! Time utility tool.use async_trait::async_trait;use chrono::{DateTime, LocalResult, NaiveDate, NaiveDateTime, TimeZone, Utc};use chrono_tz::Tz;use crate::context::JobContext;use crate::tools::tool::{Tool, ToolError, ToolOutput, require_str};/// Tool for getting current time and date operations.pub struct TimeTool;#[async_trait]impl Tool for TimeTool {    fn name(&self) -> &str {        "time"    }    fn description(&self) -> &str {        "Get current time, parse or format timestamps, convert timezones, or calculate time differences."    }    fn parameters_schema(&self) -> serde_json::Value {        serde_json::json!({            "type": "object",            "properties": {                "operation": {                    "type": "string",                    "enum": ["now", "parse", "convert", "format", "diff"],                    "description": "The time operation to perform"                },                "input": {                    "type": "string",                    "description": "Input timestamp. Accepts RFC 3339, or a naive timestamp when timezone/from_timezone is provided."                },                "timestamp": {                    "type": "string",                    "description": "Alias for input (kept for backward compatibility)."                },                "timezone": {                    "type": "string",                    "description": "IANA timezone name (e.g. 'America/New_York'). Used by now/format, and can also interpret naive timestamps."                },                "from_timezone": {                    "type": "string",                    "description": "Source IANA timezone for naive input timestamps during convert/format/diff."                },                "to_timezone": {                    "type": "string",                    "description": "Target IANA timezone for convert."                },                "format": {                    "type": "string",                    "description": "strftime format string for format (kept for backward compatibility)."                },                "format_string": {                    "type": "string",                    "description": "strftime format string for format."                },                "timestamp2": {                    "type": "string",                    "description": "Second timestamp for diff."                }            },            "required": ["operation"]        })    }    async fn execute(        &self,        params: serde_json::Value,        ctx: &JobContext,    ) -> Result<ToolOutput, ToolError> {        let start = std::time::Instant::now();        let operation = require_str(&params, "operation")?;        let result = match operation {            "now" => execute_now(&params, ctx)?,            "parse" => execute_parse(&params, ctx)?,            "convert" => execute_convert(&params, ctx)?,            "format" => execute_format(&params, ctx)?,            "diff" => execute_diff(&params, ctx)?,            _ => {                return Err(ToolError::InvalidParameters(format!(                    "unknown operation: {}",                    operation                )));            }        };        Ok(ToolOutput::success(result, start.elapsed()))    }    fn requires_sanitization(&self) -> bool {        false // Internal tool, no external data    }}